// Centrales sans connecteur Skitrack (moteurs.data.json, relevé du 11 octobre 2026).
// MAX_FICHES borne le coût Firecrawl par hôte.
const MAX_FICHES = 200;
return [
  ['beuil.fr', 'Beuil – Les Launes'],
  ['booking.prazsurarly.com', 'Praz-sur-Arly'],
  ['font-romeu.fr', 'Font-Romeu – Pyrénées 2000'],
  ['lesangles.com', 'Les Angles'],
  ['sites.valdabondance.com', 'Abondance'],
  ['www.chioula.fr', 'Le Chioula'],
  ['www.haut-giffre.fr', 'Sixt-Fer-à-Cheval'],
  ['www.mole-brasses.com', 'Les Brasses'],
  ['www.sancy.com', 'Super Besse'],
  ['www.valleesdegavarnie.com', 'Gavarnie-Gèdre'],
].map(([host, nom]) => ({ json: { host, nom, origine: 'https://' + host, max: MAX_FICHES } }));

// robots.txt lu et respecté : Disallow du groupe * (ou Skitrack), Crawl-delay, lignes Sitemap.
// Un Disallow: / hors groupe (booking.prazsurarly.com) vaut interdiction totale.
const out = [];
for (const item of $input.all()) {
  const cible = $('Cibles').itemMatching(item.pairedItem?.item ?? 0)?.json ?? item.json;
  const statut = item.json.statusCode ?? 200;
  const texte = typeof item.json.data === 'string' ? item.json.data : '';
  if (statut === 401 || statut === 403 || statut === 429) { out.push({ json: { ...cible, ignore: `refus ${statut}` } }); continue; }
  const regles = []; let delai = 0; let groupe = false; let vuUA = false; let horsGroupeTout = false;
  for (const brut of texte.split(/\r?\n/)) {
    const l = brut.replace(/#.*$/, '').trim(); if (!l) continue;
    const ua = /^user-agent\s*:\s*(.+)$/i.exec(l);
    if (ua) { const v = ua[1].trim().toLowerCase(); groupe = v === '*' || v === 'skitrack'; vuUA = true; continue; }
    if (!vuUA && /^disallow\s*:\s*\/\s*$/i.test(l)) horsGroupeTout = true;
    const d = /^(dis)?allow\s*:\s*(.*)$/i.exec(l);
    if (d && groupe && d[2]) regles.push({ allow: !d[1], motif: d[2].trim() });
    const c = /^crawl-delay\s*:\s*([0-9.]+)/i.exec(l);
    if (c && groupe) delai = Math.max(delai, Number(c[1]));
  }
  const interditRacine = horsGroupeTout || regles.some(r => !r.allow && r.motif === '/');
  out.push({ json: { ...cible, regles, delaiS: Math.max(2, Math.ceil(delai)), ignore: interditRacine ? 'robots.txt interdit tout' : null } });
}
return out;

function autorise(chemin, regles) {
  // Règle la plus longue gagnante, Allow à égalité ; * et $ gérés.
  let meilleure = null;
  for (const r of regles) {
    const re = new RegExp('^' + r.motif.replace(/[.+?^{}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\\\$$/, '$'));
    if (re.test(chemin) && (!meilleure || r.motif.length > meilleure.motif.length || (r.motif.length === meilleure.motif.length && r.allow))) meilleure = r;
  }
  return !meilleure || meilleure.allow;
}
const HEBERG = /(heberg|locati|loueur|meubl|gite|chalet|appartement|residence|studio|chambres?-d-?hote|hotel|logement|refuge)/;
const PAS = /(\/(blog|actualites?|news|agenda|evenements?|tag|category|author)\/|restaurant|restauration|activite|randonnee|commerce|patrimoine|equipement|loisir|contact|mentions)/;
const LANGUE = /^\/(en|ca|es|de|it|nl|pt)\//;
const out = [];
for (const item of $input.all()) {
  const h = $('Hôte autorisé ?').itemMatching(item.pairedItem?.item ?? 0).json;
  const liens = (item.json.links || []).map(l => l.url).filter(Boolean);
  const vus = new Set();
  for (const u of liens) {
    let p; try { p = new URL(u); } catch { continue; }
    const chemin = decodeURIComponent(p.pathname).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (!HEBERG.test(chemin) || PAS.test(chemin) || LANGUE.test(p.pathname)) continue;
    if (!autorise(p.pathname + p.search, h.regles)) continue;
    if (vus.has(p.href) || vus.size >= h.max) continue;
    vus.add(p.href);
    out.push({ json: { host: h.host, nom: h.nom, url: p.href, delaiS: h.delaiS } });
  }
}
return out;

// Mêmes bornes que src/lib/scrape/catalogue.ts : rien d'inventé, « à partir de » = plancher,
// total retenu seulement avec ses deux dates.
const PLANCHER = /(a partir de|à partir de|\bdes\b|\bdès\b|\bfrom\b|\bmini(mum)?\b)/i;
const ent = (v, a, b) => Number.isInteger(v) && v >= a && v <= b ? v : null;
const num = (v, a, b) => typeof v === 'number' && isFinite(v) && v >= a && v <= b ? v : null;
const src = $('Une fiche à la fois').item.json;
const r = $json; const d = r.data || {}; const j = d.json || {}; const statut = d.metadata?.statusCode ?? null;
if (!r.success || (statut && statut >= 400)) return [{ json: { ...src, erreur: r.error || ('HTTP ' + statut) } }];
const lat = num(j.latitude, 41, 51.5), lon = num(j.longitude, -5.5, 10);
const tarifs = (j.tarifs || []).filter(t => t && t.libelle && num(t.montant_eur, 10, 50000) != null)
  .map(t => ({ libelle: String(t.libelle).slice(0, 200), montant: t.montant_eur, unite: t.unite || 'autre', plancher: PLANCHER.test(t.libelle) }));
let total = null; const ts = j.total_sejour;
if (ts && /^\d{4}-\d{2}-\d{2}$/.test(ts.arrivee || '') && /^\d{4}-\d{2}-\d{2}$/.test(ts.depart || '') && num(ts.montant_eur, 20, 100000) != null && !PLANCHER.test(ts.libelle || '')) {
  const nuits = (Date.parse(ts.depart) - Date.parse(ts.arrivee)) / 864e5;
  if (Number.isInteger(nuits) && nuits >= 1 && nuits <= 30) total = { montant: ts.montant_eur, arrivee: ts.arrivee, depart: ts.depart, nuits };
}
return [{ json: { host: src.host, url: src.url, lecteur: 'firecrawl', titre: j.titre ?? null, type: j.type_hebergement ?? null, commune: j.commune ?? null,
  capacite: ent(j.capacite_personnes, 1, 50), chambres: ent(j.chambres, 0, 30), pieces: ent(j.pieces, 1, 30),
  lat: lat != null && lon != null ? lat : null, lon: lat != null && lon != null ? lon : null,
  photos: [...new Set((j.photos || []).filter(p => /^https?:\/\//.test(p)))].slice(0, 20), equipements: (j.equipements || []).slice(0, 60),
  tarifs, totalSejour: total, releveLe: new Date().toISOString() } }];
